/* 20しゅるい × 5いろ ＝ 100パターンを じどうで つくる */
const CRAFT_PATTERNS = (function () {
  const out = [];
  CRAFT_ITEMS.forEach(it => {
    CRAFT_COLORS.forEach(cl => {
      out.push({
        id: it.id + '_' + cl.id,
        base: it.id,
        name: cl.name + 'の ' + it.name,
        draw: it.draw,
        kind: (it.id === 'rug') ? 'floor' : 'item',
        w: it.w, h: it.h,
        x: 0.5, y: 0.78,
        cost: it.cost,
        palette: cl,
        got: 'craft',
      });
    });
  });
  return out;
})();

